### Contributing guidelines

- [x] I have read [CONTRIBUTING.md](https://github.com/nvim-mini/mini.nvim/blob/main/CONTRIBUTING.md)
- [x] I have read [CODE_OF_CONDUCT.md](https://github.com/nvim-mini/mini.nvim/blob/main/CODE_OF_CONDUCT.md)
- [x] I have updated 'mini.nvim' to latest version of the `main` branch

### Module(s)

mini.git

### Neovim version

0.11.x

### Description

when using `mini.git` with blink, blink auto-complete just closes (crashes) the gitcommit buffer. 

### Reproduction

repro config per-below

``` lua
-- Clone latest 'mini.nvim' (requires Git CLI installed)
vim.cmd('echo "Installing `mini.nvim`" | redraw')
local mini_path = vim.fn.stdpath("data") .. "/site/pack/deps/start/mini.nvim"
local clone_cmd = { "git", "clone", "--depth=1", "https://github.com/nvim-mini/mini.nvim", mini_path }
vim.fn.system(clone_cmd)
vim.cmd('echo "`mini.nvim` is installed" | redraw')

-- Make sure 'mini.nvim' is available
vim.cmd("packadd mini.nvim")
MiniDeps = require("mini.deps")
MiniDeps.setup()
MiniDeps.add({
	source = "saghen/blink.cmp",
	checkout = "v1.8.0", -- check releases for latest tag
})

local mini_git = require("mini.git")
mini_git.setup()
-- Setup Autocomplete
local cmp = require("blink.cmp")
cmp.setup({
	keymap = {
		preset = "none",
		["<C-e>"] = { "show", "show_documentation", "hide_documentation" },
		["<Esc>"] = { "cancel", "fallback" },
		["<C-f>"] = { "cancel", "fallback" },
		["<CR>"] = { "accept", "fallback" },
		["<C-u>"] = { "scroll_documentation_up", "fallback" },
		["<C-d>"] = { "scroll_documentation_down", "fallback" },
		["<Tab>"] = { "select_next", "snippet_forward", "fallback" },
		["<S-Tab>"] = { "select_prev", "snippet_backward", "fallback" },
	},

	appearance = {
		use_nvim_cmp_as_default = false,
		nerd_font_variant = "mono",
	},
	fuzzy = {
		prebuilt_binaries = { download = true },
		implementation = "rust",
	},
	completion = {
		list = { selection = { preselect = true, auto_insert = true } },
		documentation = {
			auto_show = true,
			auto_show_delay_ms = 250,
		},
	},
	sources = {
		default = { "lsp", "path", "snippets", "buffer" },
		providers = {
			lsp = {
				min_keyword_length = 1, -- Number of characters to trigger porvider
				score_offset = 0, -- Boost/penalize the score of the items
			},
			path = {
				min_keyword_length = 2,
			},
			snippets = {
				min_keyword_length = 2,
				score_offset = 5, -- Boost/penalize the score of the items
			},
			buffer = {
				min_keyword_length = 0,
				max_items = 5,
			},
		},
	},
	cmdline = {
		keymap = {
			preset = "none",
			["<C-e>"] = { "show", "show_documentation", "hide_documentation" },
			["<Esc>"] = { "cancel", "fallback" },
			["<C-f>"] = { "cancel", "fallback" },
			["<CR>"] = { "accept_and_enter", "fallback" },
			["<Tab>"] = { "select_next", "fallback" },
			["<S-Tab>"] = { "select_prev", "fallback" },
		},
		sources = function()
			local type = vim.fn.getcmdtype()
			if type == "/" or type == "?" then
				return { "buffer" }
			end
			if type == ":" or type == "@" then
				return { "cmdline" }
			end
			return {}
		end,
		completion = {
			menu = { auto_show = true },
			list = { selection = { preselect = false, auto_insert = true } },
		},
	},
	term = {
		enabled = true,
		keymap = { preset = "inherit" }, -- Inherits from top level `keymap` config when not set
		sources = { "buffer" },
		completion = {
			list = { selection = { preselect = true, auto_insert = true } },
			menu = { auto_show = false },
			ghost_text = { enabled = false },
		},
	},
})
```

per gif, when using `tab` or `<Cr>` from blink will automatically close the Git commit page. If the git commit page is opened using vim-fugitive (:G commit), blink autocomplete can be used as usually. This behavior is consistent across my home pc, wsl, work pc, rhel since it does not happen in vim-fugitive, it is more likely be a comparability issue with mini.git. 

